<script module lang="ts">
/**
 * A Button preset for copying a value to the clipboard (`design/components/copy-button.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/copy-button.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy } from 'svelte'

import { Icon, devWarning, joinSlot, watchEffect } from '@polymorph/svelte'
import styles from '@polymorph/recipes/controls/copy-button.module.css'

export interface CopyButtonProps {
  /**
   * The confirmation announced to assistive technology ("Copied"). It is required, because a
   * screen reader user cannot perceive the icon change, so an announcement must exist. The
   * vocabulary writes no prose, so the app supplies both of this member's strings.
   */
  copiedLabel: string
  disabled?: boolean
  /**
   * The accessible name ("Copy install command"). No default, because naming is a decision
   * (Button's law).
   */
  label: string
  /**
   * Button's sizes without `lg`. A copy button is secondary, and at `lg` it would look like a
   * main action.
   */
  size?: 'sm' | 'md'
  /**
   * Written to the clipboard exactly as given, including whitespace.
   */
  value: string
}
</script>

<script lang="ts">
let {
  copiedLabel,
  disabled = false,
  label: labelOwn,
  size = 'md',
  value,
}: CopyButtonProps = $props()
const joined = joinSlot(undefined, () => ({ disabled: disabled, label: labelOwn, size: size }))
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
let copied = $state(false)
let copies = $state(0)
const copy = $derived(
  () =>
    void navigator.clipboard.writeText(value).then(
      () => {
        copied = true
        copies += 1
      },
      (refusal: unknown) =>
        devWarning(true, `CopyButton could not write to the clipboard: ${String(refusal)}`),
    ),
)
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const timer = setTimeout(() => {
    copied = false
  }, 2000)
  release1 = () => clearTimeout(timer)
}
watchEffect(effect1, { watch: () => copies, mount: false })
onDestroy(() => release1?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<button
    class={styles.button}
    type="button"
    {disabled}
    aria-label={label}
    data-variant="ghost"
    data-tone="neutral"
    data-size={size}
    data-disabled={(disabled) ? '' : undefined}
    data-icon-only=""
    data-state={(copied) ? 'copied' : undefined}
    data-member="copy-button"
    onclick={() => { copy() }}
    ><span class={styles.glyphs} aria-hidden="true"
      ><span class={styles.copyGlyph}><Icon name="copy" {size} /></span
      ><span class={styles.confirmGlyph}><Icon name="confirm" {size} /></span
    ></span
  ></button
  ><span class={styles.status} role="status">{copied ? copiedLabel : ''}</span
>{/if
}{@render joined.end?.()}
